<dialog id="amenityLightbox" class="amenity-lightbox" aria-labelledby="amenityLightboxTitle">
    <div class="amenity-dialog-heading"><h2 id="amenityLightboxTitle">Amenity photo</h2><button type="button" class="service-btn service-btn-secondary" data-close-amenity>Close</button></div>
    <img id="amenityLightboxImage" alt="" decoding="async">
    <p id="amenityLightboxFallback" hidden>Photo unavailable. Please try another photo.</p>
    <div class="amenity-lightbox-nav"><button type="button" class="service-btn service-btn-secondary" data-lightbox-step="-1">Previous</button><span id="amenityLightboxCount" aria-live="polite"></span><button type="button" class="service-btn service-btn-secondary" data-lightbox-step="1">Next</button></div>
</dialog>
